for fname, data in games_data.items():
    filepath = os.path.join('src/pages/ru/games', fname)
    if not os.path.exists(filepath):
        print(f"NOT FOUND: {filepath}")
        continue
    
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # 1. Replace title and desc in frontmatter
    # title regex
    import re
    content = re.sub(r'const title = ["\'].*?["\'];', f'const title = "{data["title"]}";', content)
    content = re.sub(r'const description = ["\'].*?["\'];', f'const description = "{data["desc"]}";', content)
    
    # 2. Replace H1 if matching
    if data['h1_old'] in content:
        content = content.replace(data['h1_old'], data['h1_new'])
    else:
        # Fallback H1 regex replace
        content = re.sub(r'<h1[^>]*>.*?</h1>', data['h1_new'].strip(), content, count=1, flags=re.DOTALL)
    
    # 3. Add FAQs section before </main>
    faq_html = '''    <!-- Frequently Asked Questions -->
    <section class="border-t border-[var(--pastel-line)] dark:border-zinc-800 pt-10 pb-6">
      <div class="mb-6">
        <h2 class="text-xl sm:text-2xl font-heading font-bold text-zinc-950 dark:text-white">
          Часто задаваемые вопросы
        </h2>
        <p class="text-xs sm:text-sm text-zinc-500 dark:text-zinc-400 mt-1">
          Научные основы, методология и практические рекомендации по тренировке.
        </p>
      </div>

      <div class="space-y-3">
'''
    for q, a in data['faqs']:
        faq_html += f'''        <details class="group p-5 rounded-2xl bg-zinc-50 dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 transition-colors">
          <summary class="flex items-center justify-between cursor-pointer font-heading font-bold text-sm sm:text-base text-zinc-900 dark:text-white list-none">
            <span>{q}</span>
            <svg class="w-4 h-4 text-zinc-500 dark:text-zinc-400 group-open:rotate-180 transition-transform duration-200 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" aria-hidden="true">
              <path stroke-linecap="round" stroke-linejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" />
            </svg>
          </summary>
          <p class="text-xs sm:text-sm text-zinc-600 dark:text-zinc-300 leading-relaxed mt-3 pt-3 border-t border-zinc-200/60 dark:border-zinc-800">
            {a}
          </p>
        </details>
'''
    faq_html += '      </div>\n    </section>\n  </main>'

    if '</main>' in content:
        content = content.replace('  </main>', faq_html, 1)
        if faq_html not in content:
            content = content.replace('</main>', faq_html, 1)
    
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"PATCHED: {fname}")
